# Check for 3x3 blocks in each region
def find_3x3_blocks(grid):
    blocks = []
    rows, cols = len(grid), len(grid[0])
    for r in range(rows-2):
        for c in range(cols-2):
            color = grid[r][c]
            is_uniform = True
            for rr in range(r, r+3):
                for cc in range(c, c+3):
                    if grid[rr][cc] != color:
                        is_uniform = False
                        break
                if not is_uniform:
                    break
            if is_uniform:
                blocks.append((r, c, color))
    return blocks

