# Are there any rectangular blocks?
def get_rectangles(grid):
    rects = []
    rows, cols = len(grid), len(grid[0])
    for r in range(rows):
        seen = {}
        for c in range(cols):
            color = grid[r][c]
            if color in seen and min(seen[color]) <= c <= max(seen[color]):
                # This color spans a range in this row
                pass  # Collect more info
            else:
                seen[color] = c
    return rects

# Simple approach: find contiguous runs of same color in each row
def contiguity(grid):
    info = []
    rows, cols = len(grid), len(grid[0])
    for r in range(rows):
        runs = []
        c = 0
        while c < cols:
            if grid[r][c] != 0:
                color = grid[r][c]
                start = c
                while c < cols and grid[r][c] == color:
                    c += 1
                runs.append((color, start, c-1, c-start))
            else:
                c += 1
        info.append(runs)
    return info

left_contig = contiguity(left_region)
